"use client";

// A certificate picture for the admin screens: the stored PNG (or, for an
// approval preview, the watermarked preview blob) shown from an authenticated
// fetch. Nothing is generated by showing it.

import { useBlobUrl } from "@/lib/certificates/useCertificates";

export function ImageFrame({
  url,
  loading,
  failed,
  alt,
  emptyLabel,
}: {
  url: string | null;
  loading?: boolean;
  failed?: boolean;
  alt: string;
  emptyLabel?: string;
}) {
  return (
    <div className="relative aspect-[1404/993] w-full overflow-hidden rounded-xl border border-[var(--a-border)] bg-[var(--a-surface-2)]">
      {url ? (
        // eslint-disable-next-line @next/next/no-img-element -- an authenticated blob: URL, not optimisable by next/image
        <img src={url} alt={alt} className="h-full w-full object-contain" />
      ) : (
        <div className="absolute inset-0 grid place-items-center px-4 text-center text-sm text-[var(--a-text-faint)]">
          {loading ? (
            <div className="h-7 w-7 animate-spin rounded-full border-b-2 border-[var(--a-accent)]" role="status" aria-label="Loading" />
          ) : (
            <p>{failed ? "The preview could not be loaded." : (emptyLabel ?? "No preview")}</p>
          )}
        </div>
      )}
    </div>
  );
}

/** A stored certificate image, by API path (null when it has none). */
export default function AdminCertificateImage({
  path,
  alt,
  emptyLabel,
}: {
  path: string | null;
  alt: string;
  emptyLabel?: string;
}) {
  const { url, loading, failed } = useBlobUrl(path);
  return <ImageFrame url={url} loading={loading} failed={failed} alt={alt} emptyLabel={emptyLabel} />;
}
